Looking at the task, I need to add a `create_invoice_handler` function that:
1. Extracts id and items from the request body
2. Creates LineItem objects (validation happens in LineItem.__post_init__)
3. Creates an Invoice with customer=user
4. Calls service.create() to persist it
5. Returns (201, {"id", "created"}) on success
6. Returns (400, {"error": code}) on validation errors

I'll need to import `Invoice` and `LineItem` to create them, then catch `InvoiceError` from LineItem validation (e.g., qty <= 0) and `KeyError` for malformed request bodies.

### invoicing/api.py
```python
from .errors import InvoiceError
from .invoice import Invoice, LineItem
from .money import format_inr


def _status(err):
    return {"NOT_FOUND": 404, "FORBIDDEN": 403}.get(err.code, 400)


def get_invoice_handler(service, invoice_id, user):
    """GET /invoices/{id}: returns (status, body)."""
    try:
        inv = service.get(invoice_id, user)
        total = service.total(invoice_id, user)
    except InvoiceError as e:
        return _status(e), {"error": e.code}
    return 200, {
        "id": inv.id,
        "customer": inv.customer,
        "created": inv.created.isoformat(),
        "total": total,
        "total_display": format_inr(total),
    }


def create_invoice_handler(service, user, body):
    """POST /invoices: create an invoice, return (status, body)."""
    try:
        invoice_id = body["id"]
        items_data = body["items"]

        items = []
        for item_data in items_data:
            item = LineItem(
                sku=item_data["sku"],
                qty=item_data["qty"],
                unit_paise=item_data["unit_paise"]
            )
            items.append(item)

        invoice = Invoice(id=invoice_id, customer=user, items=items)
        service.create(invoice)

        return 201, {
            "id": invoice.id,
            "created": invoice.created.isoformat()
        }
    except KeyError:
        return 400, {"error": "BAD_AMOUNT"}
    except InvoiceError as e:
        return _status(e), {"error": e.code}
